INSERT INTO _checks(name, expected, actual) VALUES ('Q1_clientes_count_is_1', '1', (SELECT count(*)::text FROM clientes));
INSERT INTO _checks(name, expected, actual) VALUES ('Q1_clientes_max_id_is_15', '15', (SELECT coalesce(max(id)::text,'NULL') FROM clientes));
INSERT INTO _checks(name, expected, actual) VALUES ('Q1_live_id_15_is_jrosa', 'true', (SELECT (coalesce(nombre_completo,'') ILIKE '%JROSA%ASESORA%VIAJES%' OR coalesce(razon_social,'') ILIKE '%JROSA%ASESORA%VIAJES%' OR coalesce(nombre_comercial,'') ILIKE '%JROSA%ASESORA%VIAJES%')::text FROM clientes WHERE id = 15));
INSERT INTO _checks(name, expected, actual) VALUES ('Q1_reservas_count_is_1', '1', (SELECT count(*)::text FROM reservas));
INSERT INTO _checks(name, expected, actual) VALUES ('Q1_reserva_10_codigo', 'RES-1787875561067', (SELECT codigo FROM reservas WHERE id = 10));
INSERT INTO _checks(name, expected, actual) VALUES ('Q1_reserva_10_cliente_is_15', '15', (SELECT coalesce(cliente_id::text,'NULL') FROM reservas WHERE id = 10));
INSERT INTO _checks(name, expected, actual) VALUES ('Q1_pagos_ref_15_is_0', '0', (SELECT count(*)::text FROM pagos WHERE cliente_id = 15));
INSERT INTO _checks(name, expected, actual) VALUES ('Q1_cambios_prov_ref_15_known_dangling', '1', (SELECT count(*)::text FROM cambios_provisionales WHERE tabla_afectada='clientes' AND registro_id=15));
INSERT INTO _checks(name, expected, actual) VALUES ('Q1_acciones_ref_15_is_0', '0', (SELECT count(*)::text FROM acciones_pendientes WHERE tabla_objetivo='clientes' AND registro_id=15));
INSERT INTO _checks(name, expected, actual) VALUES ('Q1_not_null_columns_match', 'true', (SELECT (array_agg(column_name::text ORDER BY column_name::text) = ARRAY['compania','direccion','email','id','registrado_por','status','telefonos','tipo_cliente']::text[])::text FROM information_schema.columns WHERE table_schema='public' AND table_name='clientes' AND is_nullable='NO'));
INSERT INTO _checks(name, expected, actual) VALUES ('Q1_check_constraints_present_5', '5', (SELECT count(*)::text FROM pg_constraint WHERE conrelid='public.clientes'::regclass AND contype='c' AND conname IN ('chk_empresa_fields','clientes_compania_check','clientes_sexo_check','clientes_status_check','clientes_tipo_cliente_check')));
INSERT INTO _checks(name, expected, actual) VALUES ('Q1_trigger_fecha_editado_present', 'true', (SELECT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.clientes'::regclass AND tgname='trigger_update_clientes_fecha_editado' AND NOT tgisinternal)::text));
INSERT INTO _checks(name, expected, actual) VALUES ('Q1_audit_clientes_trigger_absent', 'true', (SELECT (NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.clientes'::regclass AND tgname ILIKE '%audit%' AND NOT tgisinternal))::text));
INSERT INTO _checks(name, expected, actual) VALUES ('Q1_serial_sequence_resolvable', 'true', ((pg_get_serial_sequence('public.clientes','id') IS NOT NULL)::text));
INSERT INTO _checks(name, expected, actual) VALUES ('Q2_staged_row_count', '1231', (SELECT count(*)::text FROM _clientes_import));
